proc sql; create table Entity as select unique
	company_id, ratingtypecode, ratingdate, ratingtime, ratingsymbol
	from raw.sp_credit_entity_rating; quit;

proc sql; create table Security as select unique
	security_id, ratingtypecode, ratingdate, ratingtime, ratingsymbol
	from raw.sp_credit_security_rating; quit;
